 155	 /// Send a simple query to Gemini CLI
 156	 pub async fn query(prompt: &str) -> Result<String> {
 157	 let output = Command::new("gemini")
 158	 .args(&["-p", prompt])
 159	 .stdin(std::process::Stdio::inherit())
 160	 .stdout(std::process::Stdio::inherit())
 161	 .stderr(std::process::Stdio::inherit())
 162	 .output()
 163	 .await
 164	 .map_err(|e| OrchestratorError::internal(format!("Failed to run Gemini CLI: {}", e)))?;
 165	
 166	 if !output.status.success() {
 167	 let stderr = String::from_utf8_lossy(&output.stderr);
 168	 let stdout = String::from_utf8_lossy(&output.stdout);
 169	 return Err(OrchestratorError::internal(format!(
 170	 "Gemini CLI failed: stderr: {}, stdout: {}",
 171	 stderr,
 172	 stdout
 173	 )));
 174	 }
 175	
 176	 let response = String::from_utf8_lossy(&output.stdout);
 177	 Ok(response.to_string())
 178	 }
