 200	#[Object]
 201	impl UserMutations {
 202	 /// Create a new user
 203	 #[graphql(guard = "VerifyTokenGuard")]
 204	 async fn sign_up(
 205	 &self,
 206	 ctx: &Context<'_>,
 207	 email: String,
 208	 password: String,
 209	 ) -> Result<domain::User> {
 210	 let pool = ctx.data_unchecked::<PgPool>();
 211	 let hash = auth::hash_password(&password)?;
 212	 let rec = sqlx::query_as!(
 213	 domain::User,
 214	 r#"
 215	 INSERT INTO users (email, password_hash)
 216	 VALUES ($1, $2)
 217	 RETURNING id, email, created_at
 218	 "#,
 219	 email,
 220	 hash
 221	 )
 222	 .fetch_one(pool)
 223	 .await?;
 224	 Ok(rec)
 225	 }
 226	}
