 278	
 279	## 5. Guard (`src/guards/verify_token.rs`)
 280	
 281	```rust
 282	use async_graphql::*;
 283	use crate::contexts::{token::Token, user_uid::UserUID};
 284	use std::sync::Arc;
 285	use tokio::sync::Mutex;
 286	
 287	pub struct VerifyTokenGuard;
 288	
 289	#[async_trait::async_trait]
 290	impl Guard for VerifyTokenGuard {
 291	 async fn check(&self, ctx: &Context<'_>) -> Result<()> {
 292	 let token = ctx
 293	 .data::<Token>()
 294	 .map_err(|_| Error::new("AUTH::Unauthorized"))?;
 295	
 296	 let user_uid = ctx.data::<Arc<Mutex<UserUID>>>()?;
 297	 let clean = token.0.trim_start_matches("Bearer ").trim();
 298	 let (uid, _) = crate::auth::extract_user_from_token(clean)
 299	 .map_err(|_| Error::new("AUTH::Unauthorized"))?;
 300	 user_uid.lock().await.update(uid);
 301	 Ok(())
 302	 }
 303	}
