 91	/// Parse configuration from command line arguments
 92	fn parse_config(args: &[String]) -> E2ETestConfig {
 93	 let mut config = E2ETestConfig::default();
 94	
 95	 let mut i = 1;
 96	 while i < args.len() {
 97	 match args[i].as_str() {
 98	 "--test-dir" => {
 99	 if i + 1 < args.len() {
 100	 config.test_app_dir = args[i + 1].clone();
 101	 i += 2;
 102	 } else {
 103	 eprintln!("❌ --test-dir requires a value");
 104	 process::exit(1);
 105	 }
 106	 }
 107	 "--max-retries" => {
 108	 if i + 1 < args.len() {
 109	 config.max_retries = args[i + 1].parse().unwrap_or(3);
 110	 i += 2;
 111	 } else {
 112	 eprintln!("❌ --max-retries requires a value");
 113	 process::exit(1);
 114	 }
 115	 }
 116	 "--timeout" => {
 117	 if i + 1 < args.len() {
 118	 config.timeout_seconds = args[i + 1].parse().unwrap_or(300);
 119	 i += 2;
 120	 } else {
 121	 eprintln!("❌ --timeout requires a value");
 122	 process::exit(1);
 123	 }
 124	 }
 125	 "--model" => {
 126	 if i + 1 < args.len() {
 127	 config.gemini_model = args[i + 1].clone();
 128	 i += 2;
 129	 } else {
 130	 eprintln!("❌ --model requires a value");
 131	 process::exit(1);
 132	 }
 133	 }
 134	 "--help" | "-h" => {
 135	 print_help();
 136	 process::exit(0);
 137	 }
 138	 _ => {
 139	 eprintln!("❌ Unknown argument: {}", args[i]);
 140	 print_help();
 141	 process::exit(1);
 142	 }
 143	 }
 144	 }
 145	
 146	 config
 147	}
