 786	 
 787	 // Use query_with_session_from_dir to enable context files access
 788	 let working_dir = self.project_path.as_ref()
 789	 .ok_or_else(|| OrchestratorError::internal("No project path set for MCP Manager"))?;
 790	 
 791	 debug!(" Using working directory: {:?}", working_dir);
 792	 debug!(" Calling Gemini CLI with gemini-2.5-flash model...");
 793	 
 794	 let response = GeminiCLI::query_with_session_from_dir(
 795	 "mcp-session", 
 796	 prompt, 
 797	 Some("gemini-2.5-flash"), 
 798	 working_dir
 799	 ).await?;
