 {\n info!(\" \ud83d\udcc1 Found 'files' array with {} entries\", file_array.len());\n for (i, file_obj) in file_array.iter().enumerate() {\n if let (Some(path), Some(content)) = (\n file_obj.get(\"path\").and_then(|p| p.as_str()),\n file_obj.get(\"content\").and_then(|c| c.as_str())\n ) {\n info!(\" {}. {} ({} chars)\", i + 1, path, content.len());\n files.push((path.to_string(), content.to_string()));\n } else {\n info!(\" {}. Invalid file object: {:?}\", i + 1, file_obj);\n }\n }\n } else {\n info!(\" \u274c No 'files' array found in JSON\");\n }\n } else {\n info!(\" \u274c Failed to parse as JSON, trying code block extraction\");\n }\n \n // If JSON parsing failed, try to extract code blocks\n if files.is_empty() {\n files = extract_code_blocks_from_response(response);\n info!(\" \ud83d\udcdd Extracted {} code blocks\", files.len());\n }\n \n // If still no files, create a basic structure\n if files.is_empty() {\n info!(\" \u26a0\ufe0f No files found, generating basic structure\");\n files.push((\"src/main.rs\".to_string(), generate_basic_main_rs()));\n files.push((\"Cargo.toml\".to_string(), generate_basic_cargo_toml()));\n }\n \n info!(\" \ud83d\udcca Total files to generate: {}\", files.len());\n Ok(files)\n}", "old_str_start_line_number": 337, "old_str_end_line_number": 361}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me also improve the file parsing to be more robust and show what's being parsed:
