use actix_web::{web, App, HttpServer, Result};

#[actix_web::main]
async fn main() -> std::io::Result<()> {
 println!("Starting Todo API server...");

 HttpServer::new(|| {
 App::new()
 .route("/", web::get().to(|| async { "Todo API is running!" }))
 })
 .bind("127.0.0.1:8080")?
 .run()
 .await
}

```

