;\n pipeline_results.add_failure(\"qa_testing\", \"Project doesn't compile, cannot proceed to QA testing\");\n pipeline_results.generate_report(&project_path);\n return;\n } else {\n info!(\" \u2705 Project builds successfully, proceeding with QA testing\");\n match run_qa_testing(&mcp_client, tech_stack, &project_files, &mut pipeline_results).await {\n Ok(test_files) => {\n info!(\" \u2705 QA testing completed with {} test files\", test_files.len());\n project_files.extend(test_files);\n }\n Err(e) => {\n error!(\" \u274c QA testing failed - stopping pipeline: {}\", e);\n pipeline_results.add_failure(\"qa_testing\", &e.to_string());\n pipeline_results.generate_report(&project_path);\n return;\n }\n }\n }", "new_str": " // Stage 4: QA Testing with iterative feedback loop\n info!(\"\\n\ud83e\uddea Stage 4: QA Testing\");\n let mut qa_iteration = 1;\n let max_qa_iterations = 3;\n let mut qa_feedback = Vec::new();\n \n loop {\n info!(\" \ud83d\udd04 QA Iteration {}/{}\", qa_iteration, max_qa_iterations);\n \n // Write files to disk temporarily to test if project builds\n let temp_test_dir = TempDir::new().expect(\"Failed to create temp test directory\");\n let test_project_path = temp_test_dir.path().to_path_buf();\n write_project_files(&test_project_path, &project_files).await;\n \n let project_builds = check_project_builds(&test_project_path).await;\n \n if !project_builds {\n let build_error = \"Project doesn't compile\";\n error!(\" \u274c {}\", build_error);\n qa_feedback.push(format!(\"Build Error (Iteration {}): {}\", qa_iteration, build_error));\n \n if qa_iteration >= max_qa_iterations {\n error!(\" \u274c Max QA iterations reached - stopping pipeline\");\n pipeline_results.add_failure(\"qa_testing\", &format!(\"Project failed to build after {} iterations\", max_qa_iterations));\n pipeline_results.generate_report(&project_path);\n return;\n }\n \n // Go back to feature development with build feedback\n info!(\" \ud83d\udd04 Going back to feature development with build feedback\");\n match run_feature_development_with_feedback(&mcp_client, &breakdown.tasks[0], tech_stack, &project_files, &qa_feedback, &mut pipeline_results).await {\n Ok(new_files) => {\n project_files = new_files; // Replace with improved files\n qa_iteration += 1;\n continue;\n }\n Err(e) => {\n error!(\" \u274c Feature development with feedback failed: {}\", e);\n pipeline_results.add_failure(\"feature_development_feedback\", &e.to_string());\n pipeline_results.generate_report(&project_path);\n return;\n }\n }\n }\n \n info!(\" \u2705 Project builds successfully, proceeding with QA testing\");\n match run_qa_testing(&mcp_client, tech_stack, &project_files, &mut pipeline_results).await {\n Ok(test_files) => {\n info!(\" \u2705 QA testing passed with {} test files\", test_files.len());\n project_files.extend(test_files);\n break; // QA passed, exit the loop\n }\n Err(e) => {\n let qa_error = e.to_string();\n warn!(\" \u26a0\ufe0f QA testing failed: {}\", qa_error);\n qa_feedback.push(format!(\"QA Rejection (Iteration {}): {}\", qa_iteration, qa_error));\n \n if qa_iteration >= max_qa_iterations {\n error!(\" \u274c Max QA iterations reached - stopping pipeline\");\n pipeline_results.add_failure(\"qa_testing\", &format!(\"QA failed after {} iterations\", max_qa_iterations));\n pipeline_results.generate_report(&project_path);\n return;\n }\n \n // Go back to feature development with QA feedback\n info!(\" \ud83d\udd04 Going back to feature development with QA feedback\");\n match run_feature_development_with_feedback(&mcp_client, &breakdown.tasks[0], tech_stack, &project_files, &qa_feedback, &mut pipeline_results).await {\n Ok(new_files) => {\n project_files = new_files; // Replace with improved files\n qa_iteration += 1;\n continue;\n }\n Err(e) => {\n error!(\" \u274c Feature development with feedback failed: {}\", e);\n pipeline_results.add_failure(\"feature_development_feedback\", &e.to_string());\n pipeline_results.generate_report(&project_path);\n return;\n }\n }\n }\n }\n }", "old_str_start_line_number": 140, "old_str_end_line_number": 169}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Excellent point! You're absolutely right. The pipeline should be iterative - when QA rejects the code, it should go back to feature development with the QA feedback added to the context, not just stop. This creates a proper feedback loop for continuous improvement.

