ion,\n feedback_context\n );\n \n let prompt = Prompts::feature_dev_todo_prompt(\n &enhanced_task_description,\n tech_stack,\n existing_files,\n Some(\"Previous implementation failed QA/build checks - must create working solution\"),\n );\n \n info!(\"\ud83d\udcdd ENHANCED FEATURE DEV PROMPT WITH FEEDBACK:\");\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", prompt);\n info!(\"{}\", \"=\".repeat(80));\n \n match GeminiCLI::query_with_model_and_retries(&prompt, \"gemini-2.0-flash-exp\", 3).await {\n Ok(response) => {\n let duration = start_time.elapsed();\n info!(\" \u2705 Feature development with feedback completed in {:.2}s\", duration.as_secs_f64());\n \n info!(\"\ud83e\udd16 ENHANCED LLM RESPONSE RECEIVED:\");\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", response);\n info!(\"{}\", \"=\".repeat(80));\n \n // Parse the response to extract file contents\n let files = parse_feature_dev_response(&response)?;\n info!(\" \ud83d\udcc4 Generated {} files with feedback incorporated\", files.len());\n \n for (path, content) in &files {\n info!(\" \ud83d\udcc4 {}: {} characters\", path, content.len());\n }\n \n results.total_files_generated += files.len();\n Ok(files)\n }\n Err(e) => {\n error!(\" \u274c Feature development with feedback failed: {}\", e);\n Err(Box::new(e))\n }\n }\n}", "old_str_start_line_number": 1119, "old_str_end_line_number": 1120}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me add the `run_feature_development_with_feedback` function that incorporates QA feedback:
