 "content": "[package]\nname = \"todo-api\"\nversion = \"0.1.0\"\nedition = \"2021\"\n\n[dependencies]\nactix-web = \"4\"\nserde = { version = \"1.0\", features = [\"derive\"] }\nserde_json = \"1.0\"\nsqlx = { version = \"0.7\", features = [\"runtime-tokio-rustls\", \"sqlite\"] }\njsonwebtoken = \"8.0\"\nbcrypt = \"0.13\"\ntokio = { version = \"1.0\", features = [\"full\"] }\ntracing = \"0.1\"\ntracing-subscriber = \"0.3\""
 }
