 {
 "Write": {
 "path": "src/main.rs",
 "content": "use actix_web::{web, App, HttpServer, Result, middleware::Logger};\nuse sqlx::SqlitePool;\nmod handlers;\nmod models;\nmod auth;\n\n#[actix_web::main]\nasync fn main() -> std::io::Result<()> {\n tracing_subscriber::init();\n \n let database_url = std::env::var(\"DATABASE_URL\")\n .unwrap_or_else(|_| \"sqlite:./todo.db\".to_string());\n \n let pool = SqlitePool::connect(&database_url)\n .await\n .expect(\"Failed to connect to database\");\n \n HttpServer::new(move || {\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .wrap(Logger::default())\n .service(handlers::health)\n .service(handlers::create_user)\n .service(handlers::login)\n .service(handlers::create_todo)\n .service(handlers::get_todos)\n .service(handlers::update_todo)\n .service(handlers::delete_todo)\n })\n .bind(\"127.0.0.1:8080\")?\n .run()\n .await\n}"
 }
