Write\": {\n \"path\": \"src/main.rs\",\n \"content\": \"mod models;\\nmod handlers;\\nmod auth;\\nmod database;\\nmod middleware;\\n\\nuse actix_web::{web, App, HttpServer, middleware::Logger};\\nuse sqlx::SqlitePool;\\nuse std::env;\\n\\n#[actix_web::main]\\nasync fn main() -> std::io::Result<()> {\\n env_logger::init();\\n \\n let database_url = env::var(\\\"DATABASE_URL\\\")\\n .unwrap_or_else(|_| \\\"sqlite:./todo.db\\\".to_string());\\n \\n let pool = SqlitePool::connect(&database_url)\\n .await\\n .expect(\\\"Failed to connect to database\\\");\\n \\n // Run migrations\\n sqlx::migrate!(\\\"./migrations\\\")\\n .run(&pool)\\n .await\\n .expect(\\\"Failed to run migrations\\\");\\n \\n println!(\\\"\ud83d\ude80 Starting Todo API server on http://127.0.0.1:8080\\\");\\n \\n HttpServer::new(move || {\\n App::new()\\n .app_data(web::Data::new(pool.clone()))\\n .wrap(Logger::default())\\n .wrap(actix_cors::Cors::permissive())\\n .service(handlers::health)\\n .service(handlers::register)\\n .service(handlers::login)\\n .service(handlers::get_todos)\\n .service(handlers::create_todo)\\n .service(handlers::update_todo)\\n .service(handlers::delete_todo)\\n .service(handlers::get_user_profile)\\n })\\n .bind(\\\"127.0.0.1:8080\\\")?\\n .run()\\n .await\\n}\"\n }\n },\n {\n \"Write\": {\n \"path\": \"src/models.rs\",\n \"content\": \"use serde::{Deserialize, Serialize};\\nuse sqlx::FromRow;\\nuse chrono::{DateTime, Utc};\\n\\n#[derive(Debug, Serialize, Deserialize, FromRow)]\\npub struct User {\\n pub id: i64,\\n pub username: String,\\n pub email: String,\\n pub password_hash: String,\\n pub created_at: DateTime<Utc>,\\n}\\n\\n#[derive(Debug, Serialize, Deserialize, FromRow)]\\npub struct Todo {\\n pub id: i64,\\n pub user_id: i64,\\n pub title: String,\\n pub description: Option<String>,\\n pub completed: bool,\\n pub created_at: DateTime<Utc>,\\n pub updated_at: DateTime<Utc>,\\n}\\n\\n#[derive(Debug, Deserialize)]\\npub struct RegisterRequest {\\n pub username: String,\\n pub email: String,\\n pub password: String,\\n}\\n\\n#[derive(Debug, Deserialize)]\\npub struct LoginRequest {\\n pub username: String,\\n pub password: String,\\n}\\n\\n#[derive(Debug, Serialize)]\\npub struct LoginResponse {\\n pub token: String,\\n pub user: UserResponse,\\n}\\n\\n#[derive(Debug, Serialize)]\\npub struct UserResponse {\\n pub id: i64,\\n pub username: String,\\n pub email: String,\\n}\\n\\n#[derive(Debug, Deserialize)]\\npub struct CreateTodoRequest {\\n pub title: String,\\n pub description: Option<String>,\\n}\\n\\n#[derive(Debug, Deserialize)]\\npub struct UpdateTodoRequest {\\n pub title: Option<String>,\\n pub description: Option<String>,\\n pub completed: Option<bool>,\\n}\\n\\n#[derive(Debug, Serialize)]\\npub struct ApiResponse<T> {\\n pub success: bool,\\n pub data: Option<T>,\\n pub message: String,\\n}\\n\\nimpl<T> ApiResponse<T> {\\n pub fn success(data: T, message: &str) -> Self {\\n Self {\\n success: true,\\n data: Some(data),\\n message: message.to_string(),\\n }\\n }\\n \\n pub fn error(message: &str) -> Self {\\n Self {\\n success: false,\\n data: None,\\n message: message.to_string(),\\n }\\n }\\n}\"\n }\n },", "old_str_start_line_number": 319, "old_str_end_line_number": 329}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me add a comprehensive example that shows ALL the files needed for a complete Todo API:
