t,\n task: &TaskInput,\n tech_stack: &str,\n existing_files: &[(String, String)],\n results: &mut PipelineResults,\n) -> Result<Vec<(String, String)>, Box<dyn std::error::Error>> {\n let start_time = Instant::now();\n \n let prompt = Prompts::feature_dev_todo_prompt(\n &format!(\"{}: {}\", task.title, task.description),\n tech_stack,\n existing_files,\n None, // no current errors\n );\n \n info!(\"\ud83d\udcdd FEATURE DEV PROMPT SENT TO LLM:\");\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", prompt);\n info!(\"{}\", \"=\".repeat(80));\n \n match GeminiCLI::query_with_model_and_retries(&prompt, \"gemini-2.0-flash-exp\", 3).await {\n Ok(response) => {\n let duration = start_time.elapsed();\n info!(\" \u2705 Feature development completed in {:.2}s\", duration.as_secs_f64());\n \n info!(\"\ud83e\udd16 LLM RESPONSE RECEIVED:\");\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", response);\n info!(\"{}\", \"=\".repeat(80));\n \n // Parse the response to extract file contents\n let files = parse_feature_dev_response(&response)?;\n info!(\" \ud83d\udcc4 Generated {} files\", files.len());\n \n for (path, content) in &files {\n info!(\" \ud83d\udcc4 {}: {} characters\", path, content.len());\n }\n \n results.total_files_generated += files.len();\n Ok(files)\n }\n Err(e) => {\n error!(\" \u274c Feature development failed: {}\", e);\n Err(Box::new(e))\n }\n }\n}", "new_str": "/// Run feature development stage with retry until working code\nasync fn run_feature_development(\n _mcp_client: &McpClient,\n task: &TaskInput,\n tech_stack: &str,\n existing_files: &[(String, String)],\n results: &mut PipelineResults,\n) -> Result<Vec<(String, String)>, Box<dyn std::error::Error>> {\n let max_attempts = 5;\n let mut attempt = 1;\n let mut feedback_history = Vec::new();\n \n loop {\n info!(\"\ud83d\udd04 Feature Development Attempt {}/{}\", attempt, max_attempts);\n \n let start_time = Instant::now();\n \n // Create prompt with accumulated feedback\n let feedback_context = if feedback_history.is_empty() {\n String::new()\n } else {\n format!(\n \"\\n\\n\ud83d\udea8 PREVIOUS ATTEMPTS FAILED - LEARN FROM THESE ERRORS:\\n{}\\n\\n\u26a0\ufe0f YOU MUST FIX ALL THESE ISSUES AND CREATE WORKING CODE:\\n\",\n feedback_history.iter().enumerate()\n .map(|(i, fb)| format!(\"Attempt {}: {}\", i + 1, fb))\n .collect::<Vec<_>>()\n .join(\"\\n\")\n )\n };\n \n let enhanced_description = format!(\n \"{}: {}\\n\\n{}\ud83c\udfaf CRITICAL: Generate COMPLETE, WORKING, TESTABLE code that builds and runs successfully.\",\n task.title, \n task.description,\n feedback_context\n );\n \n let prompt = Prompts::feature_dev_todo_prompt(\n &enhanced_description,\n tech_stack,\n existing_files,\n None,\n );\n \n info!(\"\ud83d\udcdd FEATURE DEV PROMPT SENT TO LLM (Attempt {}):\", attempt);\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", prompt);\n info!(\"{}\", \"=\".repeat(80));\n \n match GeminiCLI::query_with_model_and_retries(&prompt, \"gemini-2.0-flash-exp\", 3).await {\n Ok(response) => {\n let duration = start_time.elapsed();\n info!(\" \u2705 Feature development completed in {:.2}s\", duration.as_secs_f64());\n \n info!(\"\ud83e\udd16 LLM RESPONSE RECEIVED (Attempt {}):\", attempt);\n info!(\"{}\", \"=\".repeat(80));\n info!(\"{}\", response);\n info!(\"{}\", \"=\".repeat(80));\n \n // Parse the response to extract file contents\n let files = parse_feature_dev_response(&response)?;\n info!(\" \ud83d\udcc4 Generated {} files\", files.len());\n \n for (path, content) in &files {\n info!(\" \ud83d\udcc4 {}: {} characters\", path, content.len());\n }\n \n // Test if the generated code actually works\n info!(\"\ud83d\udd28 Testing generated code...\");\n let (works, test_output) = test_generated_code(&files, tech_stack).await;\n \n if works {\n info!(\" \u2705 Generated code works! Attempt {} successful\", attempt);\n results.total_files_generated += files.len();\n return Ok(files);\n } else {\n warn!(\" \u274c Generated code doesn't work: {}\", test_output);\n feedback_history.push(format!(\"Code failed to build/test: {}\", test_output));\n \n if attempt >= max_attempts {\n error!(\" \u274c Max attempts reached. Feature development failed after {} attempts\", max_attempts);\n return Err(format!(\"Feature development failed after {} attempts. Last error: {}\", max_attempts, test_output).into());\n }\n \n attempt += 1;\n info!(\" \ud83d\udd04 Retrying with feedback...\");\n continue;\n }\n }\n Err(e) => {\n error!(\" \u274c LLM query failed on attempt {}: {}\", attempt, e);\n feedback_history.push(format!(\"LLM query failed: {}\", e));\n \n if attempt >= max_attempts {\n return Err(Box::new(e));\n }\n \n attempt += 1;\n continue;\n }\n }\n }\n}", "old_str_start_line_number": 450, "old_str_end_line_number": 492}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"You're absolutely right! Adding too many specific examples will bias the LLM towards Rust and make it less flexible for other programming languages. The better approach is to make the feature development agent **retry until it produces working, testable code**.

