ropriate tests\n if tech_stack.to_lowercase().contains(\"rust\") {\n test_rust_project(&test_path).await\n } else if tech_stack.to_lowercase().contains(\"node\") || tech_stack.to_lowercase().contains(\"react\") || tech_stack.to_lowercase().contains(\"vue\") {\n test_node_project(&test_path).await\n } else if tech_stack.to_lowercase().contains(\"python\") {\n test_python_project(&test_path).await\n } else {\n // Generic test - just check if main files exist\n test_generic_project(&test_path, files).await\n }\n}\n\n/// Test Rust project: cargo check, cargo test, cargo build\nasync fn test_rust_project(project_path: &PathBuf) -> (bool, String) {\n info!(\" \ud83e\udd80 Testing Rust project...\");\n \n // Check if Cargo.toml exists\n if !project_path.join(\"Cargo.toml\").exists() {\n return (false, \"Missing Cargo.toml file\".to_string());\n }\n \n // Run cargo check\n info!(\" \ud83d\udce6 Running cargo check...\");\n let check_output = std::process::Command::new(\"cargo\")\n .arg(\"check\")\n .current_dir(project_path)\n .output();\n \n match check_output {\n Ok(output) => {\n if !output.status.success() {\n let stderr = String::from_utf8_lossy(&output.stderr);\n return (false, format!(\"cargo check failed: {}\", stderr));\n }\n }\n Err(e) => return (false, format!(\"Failed to run cargo check: {}\", e)),\n }\n \n // Run cargo test\n info!(\" \ud83e\uddea Running cargo test...\");\n let test_output = std::process::Command::new(\"cargo\")\n .arg(\"test\")\n .current_dir(project_path)\n .output();\n \n match test_output {\n Ok(output) => {\n let stdout = String::from_utf8_lossy(&output.stdout);\n let stderr = String::from_utf8_lossy(&output.stderr);\n \n if !output.status.success() {\n return (false, format!(\"cargo test failed: {} | {}\", stderr, stdout));\n }\n \n info!(\" \u2705 Rust project builds and tests pass\");\n (true, format!(\"Rust project successful: {}\", stdout))\n }\n Err(e) => (false, format!(\"Failed to run cargo test: {}\", e)),\n }\n}\n\n/// Test Node.js project: npm install, npm run build, npm test\nasync fn test_node_project(project_path: &PathBuf) -> (bool, String) {\n info!(\" \ud83d\udce6 Testing Node.js project...\");\n \n // Check if package.json exists\n if !project_path.join(\"package.json\").exists() {\n return (false, \"Missing package.json file\".to_string());\n }\n \n // Run npm install\n info!(\" \ud83d\udce5 Running npm install...\");\n let install_output = std::process::Command::new(\"npm\")\n .arg(\"install\")\n .current_dir(project_path)\n .output();\n \n match install_output {\n Ok(output) => {\n if !output.status.success() {\n let stderr = String::from_utf8_lossy(&output.stderr);\n return (false, format!(\"npm install failed: {}\", stderr));\n }\n }\n Err(e) => return (false, format!(\"Failed to run npm install: {}\", e)),\n }\n \n // Run npm run build\n info!(\" \ud83c\udfd7\ufe0f Running npm run build...\");\n let build_output = std::process::Command::new(\"npm\")\n .arg(\"run\")\n .arg(\"build\")\n .current_dir(project_path)\n .output();\n \n match build_output {\n Ok(output) => {\n if !output.status.success() {\n let stderr = String::from_utf8_lossy(&output.stderr);\n return (false, format!(\"npm run build failed: {}\", stderr));\n }\n }\n Err(e) => return (false, format!(\"Failed to run npm run build: {}\", e)),\n }\n \n // Test if we can start the dev server briefly\n info!(\" \ud83c\udf10 Testing UI accessibility...\");\n let ui_test_result = test_ui_accessibility(project_path).await;\n \n match ui_test_result {\n Ok(message) => {\n info!(\" \u2705 Node.js project builds and UI is accessible\");\n (true, format!(\"Node.js project successful: {}\", message))\n }\n Err(e) => (false, format!(\"UI test failed: {}\", e)),\n }\n}\n\n/// Test Python project: syntax check, pip install, run tests\nasync fn test_python_project(project_path: &PathBuf) -> (bool, String) {\n info!(\" \ud83d\udc0d Testing Python project...\");\n \n // Check for main Python files\n let has_main = project_path.join(\"main.py\").exists() || \n project_path.join(\"app.py\").exists() ||\n project_path.join(\"manage.py\").exists();\n \n if !has_main {\n return (false, \"Missing main Python file (main.py, app.py, or manage.py)\".to_string());\n }\n \n // Run Python syntax check\n info!(\" \ud83d\udd0d Running Python syntax check...\");\n let syntax_output = std::process::Command::new(\"python\")\n .arg(\"-m\")\n .arg(\"py_compile\")\n .arg(\".\")\n .current_dir(project_path)\n .output();\n \n match syntax_output {\n Ok(output) => {\n if !output.status.success() {\n let stderr = String::from_utf8_lossy(&output.stderr);\n return (false, format!(\"Python syntax check failed: {}\", stderr));\n }\n \n info!(\" \u2705 Python project syntax is valid\");\n (true, \"Python project syntax check passed\".to_string())\n }\n Err(e) => (false, format!(\"Failed to run Python syntax check: {}\", e)),\n }\n}\n\n/// Test generic project: check for essential files and structure\nasync fn test_generic_project(project_path: &PathBuf, files: &[(String, String)]) -> (bool, String) {\n info!(\" \ud83d\udcc1 Testing generic project structure...\");\n \n // Check if we have a reasonable number of files\n if files.len() < 3 {\n return (false, format!(\"Too few files generated: {} (minimum 3 expected)\", files.len()));\n }\n \n // Check if files actually exist on disk\n let mut missing_files = Vec::new();\n for (path, _) in files {\n if !project_path.join(path).exists() {\n missing_files.push(path.clone());\n }\n }\n \n if !missing_files.is_empty() {\n return (false, format!(\"Missing files on disk: {:?}\", missing_files));\n }\n \n info!(\" \u2705 Generic project structure looks good\");\n (true, format!(\"Generic project has {} files with proper structure\", files.len()))\n}\n\n/// Test UI accessibility by starting dev server briefly\nasync fn test_ui_accessibility(project_path: &PathBuf) -> Result<String, String> {\n use std::time::Duration;\n use tokio::time::timeout;\n \n // Try to start dev server in background\n let mut child = std::process::Command::new(\"npm\")\n .arg(\"run\")\n .arg(\"dev\")\n .current_dir(project_path)\n .stdout(std::process::Stdio::piped())\n .stderr(std::process::Stdio::piped())\n .spawn()\n .map_err(|e| format!(\"Failed to start dev server: {}\", e))?;\n \n // Wait a few seconds for server to start\n tokio::time::sleep(Duration::from_secs(5)).await;\n \n // Try to make HTTP request to common dev server ports\n let ports = [3000, 5173, 8080, 4200, 3001];\n let mut server_accessible = false;\n let mut accessible_port = 0;\n \n for port in ports {\n if let Ok(_) = timeout(Duration::from_secs(2), \n reqwest::get(&format!(\"http://localhost:{}\", port))\n ).await {\n server_accessible = true;\n accessible_port = port;\n break;\n }\n }\n \n // Kill the dev server\n let _ = child.kill();\n let _ = child.wait();\n \n if server_accessible {\n Ok(format!(\"UI accessible on port {}\", accessible_port))\n } else {\n Err(\"UI not accessible on common ports\".to_string())\n }\n}", "old_str_start_line_number": 1157, "old_str_end_line_number": 1158}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Perfect! You want the feature development agent to retry until it produces working code that actually builds and runs, and also verify the UI if it's a frontend application. Let me implement a robust retry mechanism with build/test validation.

