extract_code_blocks_from_response(response);\n info!(\" \ud83d\udcdd Extracted {} code blocks\", files.len());\n }\n\n // If still no files, LLM failed to generate proper response\n if files.is_empty() {\n info!(\" \u274c No files found - LLM must generate proper project structure\");\n return Err(\"LLM failed to generate any files - prompt needs improvement\".into());\n }\n\n info!(\" \ud83d\udcca Total files to generate: {}\", files.len());\n Ok(files)\n}", "new_str": "/// Parse feature development response to extract and execute todo actions\nasync fn parse_feature_dev_response(response: &str) -> Result<Vec<(String, String)>, Box<dyn std::error::Error>> {\n use orchy::enums::action::Action;\n \n let mut files = Vec::new();\n\n info!(\"\ud83d\udd0d PARSING LLM RESPONSE FOR TODO ACTIONS:\");\n\n // Extract JSON from markdown code blocks if present\n let json_content = extract_json_from_response(response);\n \n // Try to parse as JSON todo array\n if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(&json_content) {\n info!(\" \u2705 Successfully parsed as JSON\");\n \n // Handle array of todos\n if let Some(todo_array) = parsed.as_array() {\n info!(\" \ud83d\udccb Found {} todos to execute\", todo_array.len());\n \n for (todo_idx, todo) in todo_array.iter().enumerate() {\n if let Some(todo_title) = todo.get(\"todo\").and_then(|t| t.as_str()) {\n info!(\" \ud83c\udfaf TODO {}: {}\", todo_idx + 1, todo_title);\n \n if let Some(actions_array) = todo.get(\"actions\").and_then(|a| a.as_array()) {\n info!(\" \ud83d\udcdd Executing {} actions\", actions_array.len());\n \n // Convert actions array to JSON string for Action::from_json_array\n let actions_json = serde_json::to_string(actions_array)?;\n \n match Action::from_json_array(&actions_json) {\n Ok(actions) => {\n info!(\" \u2705 Parsed {} actions successfully\", actions.len());\n \n // Execute actions and collect files\n for (action_idx, action) in actions.iter().enumerate() {\n match action {\n Action::Write { path, content } => {\n // Clean up the path (remove todo-api/ prefix if present)\n let clean_path = path.strip_prefix(\"todo-api/\").unwrap_or(path);\n info!(\" \ud83d\udcc4 Action {}: Write {} ({} chars)\", action_idx + 1, clean_path, content.len());\n files.push((clean_path.to_string(), content.clone()));\n }\n Action::RunCommand { command, .. } => {\n info!(\" \ud83d\udd27 Action {}: RunCommand: {}\", action_idx + 1, command);\n // For now, just log the command - in a real implementation, execute it\n }\n _ => {\n info!(\" \u26a1 Action {}: {:?}\", action_idx + 1, action);\n }\n }\n }\n }\n Err(e) => {\n warn!(\" \u274c Failed to parse actions: {}\", e);\n }\n }\n }\n }\n }\n } else {\n info!(\" \u274c JSON is not an array of todos\");\n }\n } else {\n info!(\" \u274c Failed to parse as JSON, trying code block extraction\");\n files = extract_code_blocks_from_response(response);\n info!(\" \ud83d\udcdd Extracted {} code blocks\", files.len());\n }\n\n // If still no files, LLM failed to generate proper response\n if files.is_empty() {\n info!(\" \u274c No files found - LLM must generate proper project structure\");\n return Err(\"LLM failed to generate any files - prompt needs improvement\".into());\n }\n\n info!(\" \ud83d\udcca Total files to generate: {}\", files.len());\n Ok(files)\n}", "old_str_start_line_number": 542, "old_str_end_line_number": 595}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Perfect! You're absolutely right. The `Action` enum already has all the parsing and execution functionality we need:

