 108	impl Action {
 109	 /// Deserialize a JSON string containing an array of actions
 110	 ///
 111	 /// This is used to parse the output from `conflict_resolution_user_prompt`
 112	 /// and `feature_development_user_prompt`.
 113	 ///
 114	 /// # Example
 115	 /// ```rust
 116	 /// use orchy::enums::Action;
 117	 ///
 118	 /// let json = r#"[
 119	 /// {
 120	 /// "Write": {
 121	 /// "path": "src/main.rs",
 122	 /// "content": "fn main() { println!(\"Hello, world!\"); }"
 123	 /// }
 124	 /// },
 125	 /// {
 126	 /// "Read": {
 127	 /// "path": "src/lib.rs"
 128	 /// }
 129	 /// }
 130	 /// ]"#;
 131	 ///
 132	 /// let actions = Action::from_json_array(json).unwrap();
 133	 /// assert_eq!(actions.len(), 2);
 134	 /// ```
 135	 pub fn from_json_array(json_str: &str) -> Result<Vec<Action>, serde_json::Error> {
 136	 serde_json::from_str(json_str)
 137	 }
