 139	 /// Parse and execute actions from a JSON string in one step
 140	 ///
 141	 /// This is a convenience function for processing prompt outputs.
 142	 /// It combines `from_json_array` and `execute_batch` into a single call.
 143	 ///
 144	 /// # Example
 145	 /// ```rust,no_run
 146	 /// use orchy::enums::Action;
 147	 ///
 148	 /// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 149	 /// let json_output = r#"[
 150	 /// {
 151	 /// "Write": {
 152	 /// "path": "hello.txt",
 153	 /// "content": "Hello, World!"
 154	 /// }
 155	 /// }
 156	 /// ]"#;
 157	 ///
 158	 /// Action::parse_and_execute(json_output).await?;
 159	 /// # Ok(())
 160	 /// # }
 161	 /// ```
 162	 pub async fn parse_and_execute(json_str: &str) -> Result<(), Box<dyn std::error::Error>> {
 163	 let actions = Self::from_json_array(json_str)?;
...
 167	
 168	 /// Execute a batch of actions sequentially
 169	 ///
 170	 /// All actions are executed in the order they appear in the slice.
 171	 /// If any action fails, execution stops and the error is returned.
 172	 ///
 173	 /// # Example
 174	 /// ```rust,no_run
 175	 /// use orchy::enums::Action;
 176	 ///
 177	 /// # async fn example() -> Result<(), std::io::Error> {
 178	 /// let actions = vec![
 179	 /// Action::Write {
 180	 /// path: "file1.txt".to_string(),
 181	 /// content: "Content 1".to_string(),
 182	 /// },
 183	 /// Action::Write {
 184	 /// path: "file2.txt".to_string(),
 185	 /// content: "Content 2".to_string(),
 186	 /// },
 187	 /// ];
 188	 ///
 189	 /// Action::execute_batch(&actions).await?;
 190	 /// # Ok(())
 191	 /// # }
 192	 /// ```
 193	 pub async fn execute_batch(actions: &[Action]) -> Result<(), std::io::Error> {
 194	 use tracing::debug;
 195	 debug!(" Starting batch execution of {} actions", actions.len());
 196	 
 197	 for (index, action) in actions.iter().enumerate() {
 198	 debug!("⚡ Executing action {}/{}: {:?}", index + 1, actions.len(), action);
 199	 match action.execute().await {
 200	 Ok(_) => {
 201	 debug!("✅ Action {}/{} completed successfully", index + 1, actions.len());
 202	 }
 203	 Err(e) => {
 204	 debug!("❌ Action {}/{} failed: {}", index + 1, actions.len(), e);
 205	 return Err(e);
 206	 }
 207	 }
 208	 }
 209	 debug!(" Batch execution completed successfully");
 210	 Ok(())
 211	 }
