 213	 pub async fn execute(&self) -> Result<(), std::io::Error> {
 214	 match self {
 215	 Action::Write { path, content } => {
 216	 use tracing::debug;
 217	 debug!(" Write action: Creating file '{}'", path);
 218	 let file_path = PathBuf::from(path);
 219	
 220	 // Create parent directories if they don't exist
 221	 if let Some(parent) = file_path.parent() {
 222	 debug!(" Creating parent directories: {:?}", parent);
 223	 fs::create_dir_all(parent).await?;
 224	 debug!("✅ Parent directories created");
 225	 }
 226	
 227	 debug!(" Creating file: {:?}", file_path);
 228	 let mut file = fs::File::create(&file_path).await?;
 229	 
 230	 debug!("✍️ Writing {} bytes to file", content.len());
 231	 file.write_all(content.as_bytes()).await?;
 232	 file.flush().await?;
 233	 
 234	 debug!("✅ Successfully wrote file '{}' ({} bytes)", path, content.len());
 235	 
 236	 // Verify file was created
 237	 if file_path.exists() {
 238	 debug!(" File verification: '{}' exists", path);
 239	 } else {
 240	 debug!("⚠️ File verification: '{}' does not exist after write!", path);
 241	 }
 242	 }
 243	
 244	 Action::Read { path } => {
 245	 let file_path = PathBuf::from(path);
 246	 let content = fs::read_to_string(&file_path).await?;
 247	 debug!("Read from {}: {}", path, content);
 248	 }
 249	
 250	 Action::Delete { path } => {
 251	 let file_path = PathBuf::from(path);
 252	 fs::remove_file(&file_path).await?;
 253	 debug!("Deleted {}", path);
 254	 }
 255	
 256	 Action::Update { path, content } => {
 257	 let file_path = PathBuf::from(path);
 258	 let mut file = fs::File::create(&file_path).await?;
 259	 file.write_all(content.as_bytes()).await?;
 260	 debug!("Updated {}", path);
 261	 }
 262	
 263	 Action::Replace {
 264	 path,
 265	 old_content,
 266	 new_content,
 267	 } => {
 268	 let file_path = PathBuf::from(path);
 269	 let content = fs::read_to_string(&file_path).await?;
 270	 let updated_content = content.replace(old_content, new_content);
 271	 fs::write(&file_path, updated_content).await?;
 272	 debug!("Replaced content in {}", path);
 273	 }
...
 303	
 304	 Action::Grep { pattern, path, recursive, case_sensitive } => {
 305	 let regex = if *case_sensitive {
 306	 Regex::new(pattern).map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidInput, e))?
 307	 } else {
 308	 Regex::new(&format!("(?i){}", pattern)).map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidInput, e))?
 309	 };
 310	
 311	 if *recursive {
 312	 Self::grep_recursive(&regex, path).await?;
 313	 } else {
 314	 Self::grep_file(&regex, path).await?;
 315	 }
 316	 }
 317	
 318	 Action::CreateDirectory { path } => {
 319	 let dir_path = PathBuf::from(path);
 320	 fs::create_dir_all(&dir_path).await?;
 321	 debug!("Created directory {}", path);
 322	 }
...
 375	
 376	 Action::Append { path, content } => {
 377	 let file_path = PathBuf::from(path);
 378	 let mut file = fs::OpenOptions::new()
 379	 .create(true)
 380	 .append(true)
 381	 .open(&file_path)
 382	 .await?;
 383	 file.write_all(content.as_bytes()).await?;
 384	 file.flush().await?;
 385	 debug!("Appended to {}", path);
 386	 }
 387	
 388	 Action::Backup { path, backup_suffix } => {
 389	 let file_path = PathBuf::from(path);
 390	 let suffix = backup_suffix.as_deref().unwrap_or(".bak");
 391	 let backup_path = format!("{}{}", path, suffix);
 392	 let content = fs::read(&file_path).await?;
 393	 fs::write(&backup_path, content).await?;
 394	 debug!("Created backup {} -> {}", path, backup_path);
 395	 }
...
 415	
 416	 Action::Extract { archive_path, destination } => {
 417	 let archive_path_buf = PathBuf::from(archive_path);
 418	 let extension = archive_path_buf.extension()
 419	 .and_then(|ext| ext.to_str())
 420	 .unwrap_or("");
 421	
 422	 let command = match extension {
 423	 "zip" => format!("unzip -q '{}' -d '{}'", archive_path, destination),
 424	 "tar" => format!("tar -xf '{}' -C '{}'", archive_path, destination),
 425	 "gz" if archive_path.ends_with(".tar.gz") => {
 426	 format!("tar -xzf '{}' -C '{}'", archive_path, destination)
 427	 },
 428	 _ => return Err(std::io::Error::new(
 429	 std::io::ErrorKind::InvalidInput,
 430	 format!("Unsupported archive format: {}", extension)
 431	 )),
 432	 };
...
 451	
 452	 Action::Archive { source_paths, archive_path, format } => {
 453	 let sources = source_paths.join(" ");
 454	 let command = match format.as_str() {
 455	 "zip" => format!("zip -r '{}' {}", archive_path, sources),
 456	 "tar" => format!("tar -cf '{}' {}", archive_path, sources),
 457	 "tar.gz" => format!("tar -czf '{}' {}", archive_path, sources),
 458	 _ => return Err(std::io::Error::new(
 459	 std::io::ErrorKind::InvalidInput,
 460	 format!("Unsupported archive format: {}", format)
 461	 )),
 462	 };
 463	
 464	 let output = Command::new("sh")
 465	 .arg("-c")
 466	 .arg(&command)
 467	 .output()
 468	 .await?;
 469	
 470	 if !output.status.success() {
 471	 return Err(std::io::Error::new(
 472	 std::io::ErrorKind::Other,
 473	 format!("Archive creation failed: {}", String::from_utf8_lossy(&output.stderr))
 474	 ));
 475	 }
