 789	 .ok_or_else(|| OrchestratorError::internal("No project path set for MCP Manager"))?;
 790	 
 791	 debug!(" Using working directory: {:?}", working_dir);
 792	 debug!(" Calling Gemini CLI with gemini-2.5-flash model...");
 793	 
 794	 let response = GeminiCLI::query_with_session_from_dir(
 795	 "mcp-session", 
 796	 prompt, 
 797	 Some("gemini-2.5-flash"), 
 798	 working_dir
 799	 ).await?;
 800	 
 801	 debug!(" Received response from Gemini ({} characters)", response.len());
 802	 debug!(" Response preview: {}", &response[..response.len().min(500)]);
 803	 
 804	 Ok(response)
 805	 }
 806	 McpModel::Claude => {
 807	 // Claude implementation would go here
 808	 debug!("❌ Claude integration not yet implemented");
 809	 Err(OrchestratorError::internal("Claude integration not yet implemented"))
 810	 }
 811	 }
 812	 }
