 1	use clap::{Arg, Command};
 2	use orchy::utils::*;
 3	use tracing::debug;
 4	
 5	#[tokio::main]
 6	async fn main() {
 7	 // Initialize tracing subscriber
 8	 tracing_subscriber::fmt::init();
 9	 
 10	 // Load environment variables from .env file
 11	 dotenv::dotenv().ok();
 12	 let app = build_cli();
 13	 let matches = app.get_matches();
 14	
 15	 match matches.subcommand() {
 16	 Some(("create", sub_matches)) => {
 17	 if let Err(e) = handle_create_project(sub_matches).await {
 18	 debug!("Error creating project: {}", e);
 19	 std::process::exit(1);
 20	 }
 21	 }
 22	 Some(("list-tasks", _)) => {
 23	 if let Err(e) = handle_list_tasks().await {
 24	 debug!("Error listing tasks: {}", e);
 25	 std::process::exit(1);
 26	 }
 27	 }
 28	 Some(("list-agents", _)) => {
 29	 if let Err(e) = handle_list_agents().await {
 30	 debug!("Error listing agents: {}", e);
 31	 std::process::exit(1);
 32	 }
 33	 }
 34	 Some(("list-issues", _)) => {
 35	 if let Err(e) = handle_list_issues().await {
 36	 debug!("Error listing issues: {}", e);
 37	 std::process::exit(1);
 38	 }
 39	 }
 40	 Some(("add-sample-data", sub_matches)) => {
 41	 if let Err(e) = handle_add_sample_data(sub_matches).await {
 42	 debug!("Error adding sample data: {}", e);
 43	 std::process::exit(1);
 44	 }
 45	 }
 46	 Some(("tui", _)) | Some(("ui", _)) => {
 47	 if let Err(e) = run_tui().await {
 48	 debug!("Error in TUI mode: {}", e);
 49	 std::process::exit(1);
 50	 }
 51	 }
 52	 Some(("add-agent", sub_matches)) => {
 53	 if let Err(e) = handle_add_agent(sub_matches).await {
 54	 debug!("Error adding agent: {}", e);
 55	 std::process::exit(1);
 56	 }
 57	 }
 58	 _ => {
 59	 // Default to TUI mode when no subcommand is provided
 60	 if let Err(e) = run_tui().await {
 61	 debug!("Error in TUI mode: {}", e);
 62	 std::process::exit(1);
 63	 }
 64	 }
 65	 }
 66	}
 67	
 68	/// Build the CLI application
 69	fn build_cli() -> Command {
 70	 Command::new("orchy")
 71	 .version("0.1.0")
 72	 .author("Orchy Team")
 73	 .about("A powerful project orchestration and management tool")
 74	 .subcommand_required(false)
 75	 .arg_required_else_help(false)
 76	 .subcommand(
 77	 Command::new("create")
 78	 .about("Create a new project")
 79	 .arg(
 80	 Arg::new("name")
 81	 .short('n')
 82	 .long("name")
 83	 .value_name("NAME")
 84	 .help("Project name")
 85	 .required(true)
 86	 )
 87	 .arg(
 88	 Arg::new("idea")
 89	 .short('i')
 90	 .long("idea")
 91	 .value_name("IDEA")
 92	 .help("Project idea/description")
 93	 .required(true)
 94	 )
 95	 .arg(
 96	 Arg::new("path")
 97	 .short('p')
 98	 .long("path")
 99	 .value_name("PATH")
 100	 .help("Project path")
 101	 .required(true)
 102	 )
