 251	## 4. Context wiring (`src/graphql/mod.rs`)
 252	
 253	```rust
 254	pub use mutations::MutationRoot;
 255	pub use queries::QueryRoot;
 256	pub use subscriptions::SubscriptionRoot;
 257	
 258	use async_graphql::Schema;
 259	use tokio_postgres::Client;
 260	use std::sync::Arc;
 261	use tokio::sync::Mutex;
 262	
 263	use crate::contexts::user_uid::UserUID;
 264	
 265	pub type PointIdSchema = Schema<QueryRoot, MutationRoot, SubscriptionRoot>;
 266	
 267	pub fn create_schema_dynamic_context(
 268	 db: Arc<Client>,
 269	) -> PointIdSchema {
 270	 Schema::build(QueryRoot, MutationRoot, SubscriptionRoot)
 271	 .data(db)
 272	 .data(Arc::new(Mutex::new(UserUID::new())))
 273	 .finish()
 274	}
 275	```
