 13	impl GeminiCLI {
 14	 /// Check if Gemini CLI is available and working
 15	 pub async fn is_available() -> bool {
 16	 match Command::new("gemini").arg("--version").output().await {
 17	 Ok(output) => output.status.success(),
 18	 Err(_) => false,
 19	 }
 20	 }
 21	
 22	 /// Get Gemini CLI version
 23	 pub async fn version() -> Result<String> {
 24	 let output = Command::new("gemini")
 25	 .arg("--version")
 26	 .output()
 27	 .await
 28	 .map_err(|e| OrchestratorError::internal(format!("Failed to get Gemini version: {}", e)))?;
 29	
 30	 if !output.status.success() {
 31	 return Err(OrchestratorError::internal("Gemini CLI not available"));
 32	 }
 33	
 34	 let version = String::from_utf8_lossy(&output.stdout);
 35	 Ok(version.trim().to_string())
 36	 }
