 149	/// Print help message
 150	fn print_help() {
 151	 println!("E2E Prompt Calibration Test Runner");
 152	 println!();
 153	 println!("USAGE:");
 154	 println!(" cargo run --bin e2e_prompt_calibration [OPTIONS]");
 155	 println!();
 156	 println!("OPTIONS:");
 157	 println!(" --test-dir <DIR> Directory for test applications (default: testing_apps)");
 158	 println!(" --max-retries <NUM> Maximum number of retries per stage (default: 3)");
 159	 println!(" --timeout <SECONDS> Timeout for each operation (default: 300)");
 160	 println!(" --model <MODEL> Gemini model to use (default: gemini-2.5-flash)");
 161	 println!(" --help, -h Show this help message");
 162	 println!();
 163	 println!("EXAMPLES:");
 164	 println!(" cargo run --bin e2e_prompt_calibration");
 165	 println!(" cargo run --bin e2e_prompt_calibration --test-dir my_tests --max-retries 5");
