 175	/// Print test summary
 176	fn print_test_summary(results: &[orchy::e2e_tests::PipelineResult]) {
 177	 println!(" TEST SUMMARY");
 178	 println!("{}", "-".repeat(40));
 179	
 180	 for result in results {
 181	 println!();
 182	 println!(" {} Pipeline:", result.pipeline_type.to_uppercase());
 183	 println!(" App: {}", result.app_name);
 184	 println!(" Status: {}", if result.overall_success { "✅ PASS" } else { "❌ FAIL" });
 185	 println!(" Duration: {}ms", result.total_duration_ms);
 186	 
 187	 println!(" Stages:");
 188	 for stage in &result.stages {
 189	 let status_icon = if stage.success { "✅" } else { "❌" };
 190	 println!(" {} {} ({}ms, {} retries)", 
 191	 status_icon, stage.stage_name, stage.duration_ms, stage.retry_count);
 192	 
 193	 if !stage.errors.is_empty() {
 194	 println!(" Errors: {}", stage.errors.len());
 195	 }
 196	 }
 197	
 198	 println!(" Final App Status:");
 199	 let status = &result.final_app_status;
 200	 println!(" Builds: {}", if status.builds_successfully { "✅" } else { "❌" });
 201	 println!(" Tests: {}", if status.tests_pass { "✅" } else { "❌" });
 202	 println!(" Deploy Ready: {}", if status.deployment_ready { "✅" } else { "❌" });
 203	 println!(" Functionality: {}", if status.functionality_works { "✅" } else { "❌" });
 204	 println!(" Performance: {}", if status.performance_acceptable { "✅" } else { "❌" });
 205	 }
 206	
 207	 println!();
 208	 println!("{}", "-".repeat(40));
 209	 
 210	 let total_pipelines = results.len();
 211	 let successful_pipelines = results.iter().filter(|r| r.overall_success).count();
 212	 let total_stages = results.iter().map(|r| r.stages.len()).sum::<usize>();
 213	 let successful_stages = results.iter()
 214	 .flat_map(|r| &r.stages)
 215	 .filter(|s| s.success)
 216	 .count();
 217	
 218	 println!(" OVERALL STATISTICS:");
 219	 println!(" Pipelines: {}/{} successful ({:.1}%)", 
 220	 successful_pipelines, total_pipelines, 
 221	 (successful_pipelines as f64 / total_pipelines as f64) * 100.0);
 222	 println!(" Stages: {}/{} successful ({:.1}%)", 
 223	 successful_stages, total_stages,
 224	 (successful_stages as f64 / total_stages as f64) * 100.0);
 225	
 226	 let total_duration: u128 = results.iter().map(|r| r.total_duration_ms).sum();
 227	 println!(" Total Duration: {}ms ({:.1}s)", total_duration, total_duration as f64 / 1000.0);
 228	
 229	 if successful_pipelines == total_pipelines {
 230	 println!();
 231	 println!(" ALL PIPELINES SUCCESSFUL!");
 232	 println!(" The prompts are well-calibrated and can handle:");
 233	 println!(" ✅ Frontend development (Vue.js login page)");
 234	 println!(" ✅ Backend development (GraphQL server)");
 235	 println!(" ✅ Error recovery and edge cases");
 236	 println!(" ✅ Complete development lifecycle");
 237	 } else {
 238	 println!();
 239	 println!("⚠️ SOME PIPELINES FAILED!");
 240	 println!(" Prompt calibration needed for:");
 241	 
 242	 for result in results {
 243	 if !result.overall_success {
 244	 println!(" ❌ {} pipeline", result.pipeline_type);
 245	 for stage in &result.stages {
 246	 if !stage.success {
 247	 println!(" - {} stage", stage.stage_name);
 248	 }
 249	 }
 250	 }
 251	 }
 252	 }
 253	}
