 164	 /// Send a query with specific model selection
 165	 pub async fn query_with_model(prompt: &str, model: &str) -> Result<String> {
 166	 let mut command = Command::new("gemini");
 167	 
 168	 // Ensure GEMINI_API_KEY is set from environment
 169	 if let Ok(api_key) = std::env::var("GEMINI_API_KEY") {
 170	 command.env("GEMINI_API_KEY", api_key);
 171	 }
 172	 
 173	 let output = command
 174	 .args(&["gen", "-m", model, "-p", prompt])
 175	 .output()
 176	 .await
 177	 .map_err(|e| OrchestratorError::internal(format!("Failed to run Gemini CLI: {}", e)))?;
 178	
 179	 if !output.status.success() {
 180	 let stderr = String::from_utf8_lossy(&output.stderr);
 181	 let stdout = String::from_utf8_lossy(&output.stdout);
 182	 return Err(OrchestratorError::internal(format!(
 183	 "Gemini CLI failed: stderr: {}, stdout: {}",
 184	 stderr,
 185	 stdout
 186	 )));
 187	 }
 188	
 189	 let response = String::from_utf8_lossy(&output.stdout);
 190	 Ok(response.to_string())
 191	 }
