 "Write": {
 "path": "src/handlers.rs",
 "content": "use actix_web::{web, HttpResponse, Result};\nuse sqlx::SqlitePool;\nuse crate::models::*;\n\n#[actix_web::get(\"/health\")]\npub async fn health() -> Result<HttpResponse> {\n Ok(HttpResponse::Ok().json(serde_json::json!({\n \"status\": \"healthy\",\n \"timestamp\": chrono::Utc::now()\n })))\n}\n\n#[actix_web::post(\"/users\")]\npub async fn create_user(\n pool: web::Data<SqlitePool>,\n user_data: web::Json<CreateUser>,\n) -> Result<HttpResponse> {\n let password_hash = bcrypt::hash(&user_data.password, bcrypt::DEFAULT_COST)\n .map_err(|_| actix_web::error::ErrorInternalServerError(\"Password hashing failed\"))?;\n \n let result = sqlx::query!(\n \"INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)\",\n user_data.username,\n user_data.email,\n password_hash\n )\n .execute(pool.get_ref())\n .await;\n \n match result {\n Ok(_) => Ok(HttpResponse::Created().json(serde_json::json!({\n \"message\": \"User created successfully\"\n }))),\n Err(_) => Ok(HttpResponse::BadRequest().json(serde_json::json!({\n \"error\": \"User creation failed\"\n })))\n }\n}"
 }
 },
 {
