 1206	/// Check if project has essential files for a Rust project
 1207	fn has_essential_files(files: &[(String, String)]) -> bool {
 1208	 let has_cargo_toml = files.iter().any(|(path, _)| path == "Cargo.toml");
 1209	 let has_main_or_lib = files.iter().any(|(path, _)|
 1210	 path == "src/main.rs" || path == "src/lib.rs"
 1211	 );
 1212	
 1213	 info!(" Essential files check:");
 1214	 info!(" Cargo.toml: {}", if has_cargo_toml { "✅" } else { "❌" });
 1215	 info!(" src/main.rs or src/lib.rs: {}", if has_main_or_lib { "✅" } else { "❌" });
 1216	
 1217	 has_cargo_toml && has_main_or_lib
 1218	}
