 1262	/// Test generic project: check for essential files and structure
 1263	async fn test_generic_project(project_path: &PathBuf, files: &[(String, String)]) -> (bool, String) {
 1264	 info!(" Testing generic project structure...");
 1265	
 1266	 // Check if we have a reasonable number of files
 1267	 if files.len() < 3 {
 1268	 return (false, format!("Too few files generated: {} (minimum 3 expected)", files.len()));
 1269	 }
 1270	
 1271	 // Check if files actually exist on disk
 1272	 let mut missing_files = Vec::new();
 1273	 for (path, _) in files {
 1274	 if !project_path.join(path).exists() {
 1275	 missing_files.push(path.clone());
 1276	 }
 1277	 }
 1278	
 1279	 if !missing_files.is_empty() {
 1280	 return (false, format!("Missing files on disk: {:?}", missing_files));
 1281	 }
 1282	
 1283	 info!(" ✅ Generic project structure looks good");
 1284	 (true, format!("Generic project has {} files with proper structure", files.len()))
 1285	}
