 250	 /// Build a comprehensive prompt with common sections
 251	 pub fn build_prompt(
 252	 title: &str,
 253	 context_sections: &[(&str, &str)],
 254	 requirements_sections: &[&str],
 255	 output_format: &str,
 256	 include_json_requirements: bool,
 257	 include_guidelines: bool,
 258	 ) -> String {
 259	 let mut prompt = format!("{}\n\n", title);
 260	
 261	 // Add context sections
 262	 for (section_title, content) in context_sections {
 263	 prompt.push_str(&format!("{}:\n{}\n\n", section_title, content));
 264	 }
 265	
 266	 // Add requirements sections
 267	 if !requirements_sections.is_empty() {
 268	 prompt.push_str("COMPREHENSIVE REQUIREMENTS:\n\n");
 269	 for (i, section) in requirements_sections.iter().enumerate() {
 270	 prompt.push_str(&format!("{}. {}\n", i + 1, section));
 271	 }
 272	 prompt.push_str("\n");
 273	 }
