 587	/// Extract code blocks from markdown-style response
 588	fn extract_code_blocks_from_response(response: &str) -> Vec<(String, String)> {
 589	 let mut files = Vec::new();
 590	 let lines: Vec<&str> = response.lines().collect();
 591	 let mut i = 0;
 592	
 593	 info!(" Scanning {} lines for code blocks", lines.len());
 594	
 595	 while i < lines.len() {
 596	 if lines[i].starts_with("```") {
 597	 info!(" Found code block at line {}: {}", i + 1, lines[i]);
 598	
 599	 // Found a code block
 600	 let mut file_path = "src/generated.rs".to_string();
...
 612	 if lang_line == "rust" || lang_line == "rs" {
 613	 file_path = format!("src/lib_{}.rs", files.len());
 614	 } else if lang_line == "toml" {
 615	 file_path = "Cargo.toml".to_string();
 616	 } else if lang_line == "dockerfile" {
 617	 file_path = "Dockerfile".to_string();
 618	 } else if lang_line == "yaml" || lang_line == "yml" {
 619	 file_path = ".github/workflows/ci.yml".to_string();
 620	 }
 621	 info!(" Inferred file path: {}", file_path);
 622	 }
 623	
 624	 // Extract content
 625	 i += 1;
 626	 let mut content = Vec::new();
 627	 let _start_line = i;
 628	 while i < lines.len() && !lines[i].starts_with("```") {
 629	 content.push(lines[i]);
 630	 i += 1;
 631	 }
 632	
 633	 if !content.is_empty() {
 634	 let content_str = content.join("\n");
 635	 info!(" Extracted {} lines of content ({} chars)", content.len(), content_str.len());
 636	 files.push((file_path, content_str));
 637	 } else {
 638	 info!(" ⚠️ Empty code block");
 639	 }
 640	 }
 641	 i += 1;
 642	 }
 643	
 644	 info!(" Total code blocks extracted: {}", files.len());
 645	 files
 646	}
