 "content": "use actix_web::{web, HttpResponse, Responder, Error};\nuse diesel::prelude::*;\nuse diesel::r2d2::{self, ConnectionManager};\nuse serde::{Serialize, Deserialize};\nuse crate::models::{User, Todo};\nuse crate::auth::{generate_jwt, verify_jwt};\nuse bcrypt::{hash, verify, BcryptResult, DEFAULT_COST};\nuse std::env;\n\n#[derive(Deserialize)]\npub struct RegisterRequest {\n pub username: String,\n pub password: String,\n}\n\n#[derive(Deserialize)]\npub struct LoginRequest {\n pub username: String,\n pub password: String,\n}\n\n#[derive(Serialize)]\npub struct AuthResponse {\n pub token: String,\n}\n\npub async fn register(req: web::Json<RegisterRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::users::dsl::users;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n let hashed_password = hash(&req.password, DEFAULT_COST).unwrap();\n\n let new_user = User {\n id: 0, // Autogenerated by DB\n username: req.username.clone(),\n password_hash: hashed_password,\n created_at: chrono::Utc::now(),\n updated_at: chrono::Utc::now(),\n };\n\n diesel::insert_into(users)\n .values(&new_user)\n .execute(&mut conn)\n .expect(\"Error creating user\");\n\n Ok(HttpResponse::Ok().json(AuthResponse { token: generate_jwt(1).unwrap() })) // Assuming user ID 1 for simplicity\n}\n\npub async fn login(req: web::Json<LoginRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::users::dsl::users;\n use crate::schema::users::dsl::username;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n let user = users\n .filter(username.eq(&req.username))\n .first::<User>(&mut conn)\n .optional()\n .expect(\"Error getting user\");\n\n match user {\n Some(user) => {\n if verify(&req.password, &user.password_hash).unwrap() {\n Ok(HttpResponse::Ok().json(AuthResponse { token: generate_jwt(user.id).unwrap() }))\n } else {\n Ok(HttpResponse::Unauthorized().finish())\n }\n }\n None => Ok(HttpResponse::Unauthorized().finish()),\n }\n}\n\npub async fn create_todo(pool: web::Data<crate::database::DbPool>) -> impl Responder {\n HttpResponse::Ok().body(\"Create Todo\")\n}\n\npub async fn get_todos(pool: web::Data<crate::database::DbPool>) -> impl Responder {\n HttpResponse::Ok().body(\"Get Todos\")\n}\n\npub async fn get_todo(pool: web::Data<crate::database::DbPool>, id: web::Path<i32>) -> impl Responder {\n HttpResponse::Ok().body(format!(\"Get Todo with ID: {}\", id))\n}\n\npub async fn update_todo(pool: web::Data<crate::database::DbPool>, id: web::Path<i32>) -> impl Responder {\n HttpResponse::Ok().body(format!(\"Update Todo with ID: {}\", id))\n}\n\npub async fn delete_todo(pool: web::Data<crate::database::DbPool>, id: web::Path<i32>) -> impl Responder {\n HttpResponse::Ok().body(format!(\"Delete Todo with ID: {}\", id))\n}"
 }
