 "path": "src/handlers.rs",
 "content": "use actix_web::{web, HttpResponse, Responder, Error};\nuse diesel::prelude::*;\nuse diesel::r2d2::{self, ConnectionManager};\nuse serde::{Serialize, Deserialize};\nuse crate::models::{User, Todo, NewUser, NewTodo};\nuse crate::auth::{generate_jwt, verify_jwt};\nuse bcrypt::{hash, verify, BcryptResult, DEFAULT_COST};\nuse std::env;\nuse chrono::Utc;\n\n#[derive(Deserialize)]\npub struct RegisterRequest {\n pub username: String,\n pub password: String,\n}\n\n#[derive(Deserialize)]\npub struct LoginRequest {\n pub username: String,\n pub password: String,\n}\n\n#[derive(Serialize)]\npub struct AuthResponse {\n pub token: String,\n}\n\npub async fn register(req: web::Json<RegisterRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::users::dsl::users;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n let hashed_password = hash(&req.password, DEFAULT_COST).unwrap();\n\n let new_user = NewUser {\n username: req.username.clone(),\n password_hash: hashed_password,\n created_at: Utc::now(),\n updated_at: Utc::now(),\n };\n\n let user = diesel::insert_into(users)\n .values(&new_user)\n .execute(&mut conn)\n .expect(\"Error creating new user\");\n\n let token = generate_jwt(1).unwrap();\n Ok(HttpResponse::Ok().json(AuthResponse { token: token }))\n}\n\npub async fn login(req: web::Json<LoginRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::users::dsl::users;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n let user = users\n .filter(crate::schema::users::username.eq(&req.username))\n .first::<User>(&mut conn)\n .optional()\n .expect(\"Error getting user\");\n\n match user {\n Some(user) => {\n if verify(&req.password, &user.password_hash).unwrap() {\n let token = generate_jwt(user.id).unwrap();\n Ok(HttpResponse::Ok().json(AuthResponse { token: token }))\n } else {\n Ok(HttpResponse::Unauthorized().finish())\n }\n }\n None => Ok(HttpResponse::Unauthorized().finish()),\n }\n}\n\n#[derive(Deserialize)]\npub struct CreateTodoRequest {\n pub title: String,\n}\n\npub async fn create_todo(req: web::Json<CreateTodoRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::todos::dsl::todos;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n let new_todo = NewTodo {\n user_id: 1, // Assuming user ID 1 for now\n title: req.title.clone(),\n completed: false,\n created_at: Utc::now(),\n updated_at: Utc::now(),\n };\n\n diesel::insert_into(todos)\n .values(&new_todo)\n .execute(&mut conn)\n .expect(\"Error creating new todo\");\n\n Ok(HttpResponse::Ok().finish())\n}\n\npub async fn get_todos(pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::todos::dsl::todos;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n let results = todos.load::<Todo>(&mut conn).expect(\"Error loading todos\");\n\n Ok(HttpResponse::Ok().json(results))\n}\n\npub async fn get_todo(id: web::Path<i32>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::todos::dsl::todos;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n let todo = todos\n .filter(crate::schema::todos::id.eq(id.into_inner()))\n .first::<Todo>(&mut conn)\n .optional()\n .expect(\"Error getting todo\");\n\n match todo {\n Some(todo) => Ok(HttpResponse::Ok().json(todo)),\n None => Ok(HttpResponse::NotFound().finish()),\n }\n}\n\n#[derive(Deserialize)]\npub struct UpdateTodoRequest {\n pub title: String,\n pub completed: bool,\n}\n\npub async fn update_todo(id: web::Path<i32>,\n req: web::Json<UpdateTodoRequest>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::todos::dsl::todos;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n diesel::update(todos.filter(crate::schema::todos::id.eq(id.into_inner())))\n .set((crate::schema::todos::title.eq(&req.title),\n crate::schema::todos::completed.eq(req.completed)))\n .execute(&mut conn)\n .expect(\"Error updating todo\");\n\n Ok(HttpResponse::Ok().finish())\n}\n\npub async fn delete_todo(id: web::Path<i32>,\n pool: web::Data<crate::database::DbPool>) -> Result<HttpResponse, Error> {\n use crate::schema::todos::dsl::todos;\n\n let mut conn = pool.get().expect(\"Failed to get database connection\");\n\n diesel::delete(todos.filter(crate::schema::todos::id.eq(id.into_inner())))\n .execute(&mut conn)\n .expect(\"Error deleting todo\");\n\n Ok(HttpResponse::Ok().finish())\n}"
 }
