 "path": "tests/integration_tests.rs",
 "content": "#[cfg(test)]\nmod tests {\n use actix_web::{test, web, App};\n use todo_api::handlers::{health_check, register, login, create_todo, get_todos, get_todo, update_todo, delete_todo};\n use actix_web::http::StatusCode;\n use serde_json::json;\n use std::env;\n use todo_api::database;\n\n #[actix_rt::test]\n async fn test_health_check() {\n let app = test::init_service(\n App::new().route(\"/health\", web::get().to(health_check)),\n )\n .await;\n let req = test::TestRequest::get().uri(\"/health\").to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_register() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/register\", web::post().to(register)),\n )\n .await;\n let req_body = json!({ \"username\": \"testuser\", \"password\": \"testpassword\" });\n let req = test::TestRequest::post()\n .uri(\"/register\")\n .set_json(&req_body)\n .to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_login() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/login\", web::post().to(login)),\n )\n .await;\n let req_body = json!({ \"username\": \"testuser\", \"password\": \"testpassword\" });\n let req = test::TestRequest::post()\n .uri(\"/login\")\n .set_json(&req_body)\n .to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_create_todo() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/todos\", web::post().to(create_todo)),\n )\n .await;\n let req_body = json!({ \"title\": \"test todo\" });\n let req = test::TestRequest::post()\n .uri(\"/todos\")\n .set_json(&req_body)\n .to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_get_todos() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/todos\", web::get().to(get_todos)),\n )\n .await;\n let req = test::TestRequest::get().uri(\"/todos\").to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_get_todo() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/todos/{id}\", web::get().to(get_todo)),\n )\n .await;\n let req = test::TestRequest::get().uri(\"/todos/1\").to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_update_todo() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/todos/{id}\", web::put().to(update_todo)),\n )\n .await;\n let req_body = json!({ \"title\": \"updated todo\", \"completed\": true });\n let req = test::TestRequest::put()\n .uri(\"/todos/1\")\n .set_json(&req_body)\n .to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n\n #[actix_rt::test]\n async fn test_delete_todo() {\n let database_url = env::var(\"DATABASE_URL\").expect(\"DATABASE_URL must be set\");\n let pool = database::establish_connection(&database_url);\n\n let app = test::init_service(\n App::new()\n .app_data(web::Data::new(pool.clone()))\n .route(\"/todos/{id}\", web::delete().to(delete_todo)),\n )\n .await;\n let req = test::TestRequest::delete().uri(\"/todos/1\").to_request();\n let resp = test::call_service(&app, req).await;\n assert_eq!(resp.status(), StatusCode::OK);\n }\n}"
 }
