 220	 /// Run the MCP Manager
 221	 pub async fn run(mut self) -> Result<()> {
 222	 info!("Starting MCP Manager");
 223	
 224	 // Check model availability
 225	 self.check_model_availability().await;
 226	
 227	 while let Some(command) = self.command_rx.recv().await {
 228	 match command {
 229	 McpCommand::Shutdown => {
 230	 info!("Shutting down MCP Manager");
 231	 break;
 232	 }
 233	 _ => {
 234	 if let Err(e) = self.handle_command(command).await {
 235	 error!("Error handling MCP command: {}", e);
 236	 }
 237	 }
 238	 }
 239	 }
 240	
 241	 Ok(())
 242	 }
