 284	 fn test_retry_logic() {
 285	 let mut error = ActionError::new("Test", "Test", "Test");
 286	 
 287	 assert!(error.should_retry(3));
 288	 
 289	 error.increment_retry();
 290	 assert_eq!(error.retry_count, 1);
 291	 assert!(error.should_retry(3));
 292	 
 293	 error.increment_retry();
 294	 error.increment_retry();
 295	 assert_eq!(error.retry_count, 3);
 296	 assert!(!error.should_retry(3));
 297	 }
